const input = $input.first().json;
const required = ['tenantId','serviceRequestId','providerPhoneNumberId','providerMessageId','mediaId','traceId'];
const missing = required.filter((k) => input[k] === undefined || input[k] === null || input[k] === '');
if (missing.length) throw new Error(`CASE002_EVIDENCE_INVALID_INPUT missing=${missing.join(',')}`);

const maxBytes = Number(input.maxBytes ?? 10485760);
if (!Number.isFinite(maxBytes) || maxBytes <= 0) throw new Error('CASE002_EVIDENCE_INVALID_MAX_BYTES');

const tenantId = String(input.tenantId);
const mediaId = String(input.mediaId);
const receivedAt = input.receivedAt ? String(input.receivedAt) : new Date().toISOString();
if (Number.isNaN(Date.parse(receivedAt))) throw new Error('CASE002_EVIDENCE_RECEIVED_AT_INVALID');

return [{ json: {
  tenantId,
  serviceRequestId: String(input.serviceRequestId),
  providerPhoneNumberId: String(input.providerPhoneNumberId),
  providerMessageId: String(input.providerMessageId),
  mediaId,
  traceId: String(input.traceId),
  expectedMediaType: input.expectedMediaType ? String(input.expectedMediaType) : '',
  maxBytes,
  idempotencyKey: input.idempotencyKey ? String(input.idempotencyKey) : `case002-evidence:${tenantId}:${mediaId}`,
  evidenceId: input.evidenceId ? String(input.evidenceId) : `kapso:${mediaId}`,
  receivedAt
} }];

const media = $input.first();
const request = $('Validate Evidence Request').first().json;
if (!media.binary?.data) throw new Error('CASE002_EVIDENCE_BINARY_MISSING');

const sha = String(media.json.sha256 || '').toLowerCase();
if (!/^[a-f0-9]{64}$/.test(sha)) throw new Error('CASE002_EVIDENCE_SHA256_INVALID');

const mimeType = String(media.json.mimeType || 'application/octet-stream').toLowerCase();
const safeTenant = String(request.tenantId).replace(/[^a-zA-Z0-9._-]/g, '_').slice(0, 80) || 'tenant';

const extByMime = {
  'image/jpeg': 'jpg',
  'image/png': 'png',
  'image/webp': 'webp',
  'video/mp4': 'mp4',
  'audio/mpeg': 'mp3',
  'audio/ogg': 'ogg',
  'application/pdf': 'pdf'
};
const extension = extByMime[mimeType] || 'bin';

let evidenceType = 'document';
if (mimeType.startsWith('image/')) evidenceType = 'photo';
else if (mimeType.startsWith('video/')) evidenceType = 'video';
else if (mimeType.startsWith('audio/')) evidenceType = 'audio';

const fileName = `case002-evidence-${safeTenant}-${sha}.${extension}`;
const storagePath = `/home/node/.n8n/storage/${fileName}`;
const storageReference = `test-local-volume://case002/${safeTenant}/sha256/${sha}.${extension}`;

return [{
  json: {
    ...request,
    provider: 'kapso',
    mimeType,
    sizeBytes: Number(media.json.sizeBytes ?? 0),
    sha256: sha,
    evidenceType,
    storagePath,
    storageReference,
    retentionClass: 'level2-test'
  },
  binary: media.binary
}];

const stored = $('Prepare Evidence Storage').first().json;
const current = $input.first();
const persistedHash = String(current.json.sha256Persisted ?? current.json.data ?? '').toLowerCase();

if (!/^[a-f0-9]{64}$/.test(persistedHash)) throw new Error('CASE002_EVIDENCE_PERSISTED_HASH_INVALID');
if (persistedHash !== stored.sha256) throw new Error('CASE002_EVIDENCE_PERSISTED_HASH_MISMATCH');

return [{ json: {
  schemaVersion: 1,
  tenantId: stored.tenantId,
  serviceRequestId: stored.serviceRequestId,
  evidenceId: stored.evidenceId,
  source: 'whatsapp',
  sourceMessageId: stored.providerMessageId,
  providerMediaId: stored.mediaId,
  type: stored.evidenceType,
  mimeType: stored.mimeType,
  sizeBytes: stored.sizeBytes,
  storageReference: stored.storageReference,
  contentHash: `sha256:${persistedHash}`,
  receivedAt: stored.receivedAt,
  capturedAt: null,
  validationStatus: 'valid',
  analysisStatus: 'not_requested',
  retentionClass: stored.retentionClass
} }];
